#include <iostream>
unsigned long long fib(unsigned n){unsigned long long a=0,b=1;for(unsigned i=0;i<n;++i){auto next=a+b;a=b;b=next;}return a;}
int main(){std::cout<<fib(50)<<" "<<fib(49)<<"\n";}

#include <iostream>
#include <thread>
#include <array>
unsigned long long fib(unsigned n){unsigned long long a=0,b=1;for(unsigned i=0;i<n;++i){auto next=a+b;a=b;b=next;}return a;}
int main(){std::array<unsigned long long,2>result{};std::thread one([&]{result[0]=fib(50);});try{std::thread two([&]{result[1]=fib(49);});two.join();}catch(...){one.join();throw;}one.join();std::cout<<result[0]<<" "<<result[1]<<"\n";}
